package com.aiservice.infrastructure.security;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.Cipher; import javax.crypto.spec.*; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.*;
@Component public class AiSecretProtector {private final String key;private final SecureRandom random=new SecureRandom();public AiSecretProtector(@Value("${AI_SETTINGS_ENCRYPTION_KEY:}")String k){key=k==null?"":k.trim();}public String encrypt(String value){try{byte[] iv=new byte[12];random.nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,secret(),new GCMParameterSpec(128,iv));byte[] out=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[12+out.length];System.arraycopy(iv,0,all,0,12);System.arraycopy(out,0,all,12,out.length);return Base64.getEncoder().encodeToString(all);}catch(Exception e){throw new IllegalArgumentException("AI settings encryption is not configured",e);}}public String decrypt(String encoded){try{byte[] all=Base64.getDecoder().decode(encoded);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,secret(),new GCMParameterSpec(128,Arrays.copyOf(all,12)));return new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalArgumentException("AI settings decryption failed",e);}}private SecretKeySpec secret(){byte[] b;try{b=Base64.getDecoder().decode(key);}catch(Exception e){b=key.getBytes(StandardCharsets.UTF_8);}if(b.length!=16&&b.length!=24&&b.length!=32)throw new IllegalArgumentException("AI_SETTINGS_ENCRYPTION_KEY must be 16/24/32 bytes");return new SecretKeySpec(b,"AES");}}
